insert into private.print_supplier_quotes as current_quote
  (product_id,page_count,quantity,currency,supply_price,vat_price,total_price,source,observed_at,evidence,options,confirmed)
select q.product_id,q.page_count,1,'KRW',q.supply_price,q.vat_price,q.total_price,'WEBSITE',q.observed_at,
  'Official website PHBKMYB one-copy UI quote: https://www.redprinting.co.kr/ko/product/item/PH/PHBKMYB; rawCaptureSHA256=252d011ce103a9f59edc2b26352f00481ad7ce4b347873375e29799b5f5b2c74; Official PHBKMYB website collection reviewed on 2026-10-19 KST: Glossy Canon 285g duplex interior; SOFT Art 300g / HARD Snow 180g cover; single-sided matte cover coating. The initial 8X8 SOFT 20-80-page batch was explicitly reviewed with these same fixed options before collection. rowKey='||q.product_id||':'||q.page_count::text||':qty1; optionEvidence='||q.option_evidence,
  jsonb_build_object('coverPaper',case when right(q.product_id,5)='_HARD' then '스노우지 180g' else '아트지 300g' end,
    'coverFinish','단면 무광코팅','interiorPaper','Glossy Canon 285g','interiorPrint','양면',
    'optionContract','PHBKMYB_GLOSSY285_MATTE_DUPLEX_V1','optionEvidence',q.option_evidence),true
from captured q where true
on conflict(product_id,page_count,quantity) do update set
  currency=excluded.currency,supply_price=excluded.supply_price,vat_price=excluded.vat_price,total_price=excluded.total_price,
  source=excluded.source,observed_at=excluded.observed_at,evidence=excluded.evidence,options=excluded.options,confirmed=true
where current_quote.observed_at<excluded.observed_at;
